export function icon(name, size = 16, cls = "") {
    const body = ICONS[name] || ICONS.circle;
    return `<svg class="ag2-i${cls ? " " + cls : ""}" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${body}</svg>`;
}
